int dserver_rpc_explicit_debug_list_members(int server_socket, uint32_t process, uint32_t portset, uint64_t* out_port_count, int* out_fd) {
	dserver_rpc_call_debug_list_members_t call = {
		.header = {
			.architecture = dserver_rpc_hooks_get_architecture(),
			.pid = dserver_rpc_hooks_get_pid(),
			.tid = dserver_rpc_hooks_get_tid(),
			.number = dserver_callnum_debug_list_members,
		},
		.body = {
			.process = process,
			.portset = portset,
		},
	};
	union {
		dserver_rpc_reply_debug_list_members_t reply;
		dserver_s2c_call_t s2c;
	} reply_msg;
	int fds[1];
	int valid_fd_count;
	char controlbuf[DSERVER_RPC_HOOKS_CMSG_SPACE(sizeof(fds))];
	dserver_rpc_hooks_iovec_t call_data = {
		.iov_base = &call,
		.iov_len = sizeof(call),
	};
	dserver_rpc_hooks_msghdr_t callmsg = {
		.msg_name = dserver_rpc_hooks_get_server_address(),
		.msg_namelen = dserver_rpc_hooks_get_server_address_length(),
		.msg_iov = &call_data,
		.msg_iovlen = 1,
		.msg_control = NULL,
		.msg_controllen = 0,
	};
	dserver_rpc_hooks_iovec_t reply_data = {
		.iov_base = &reply_msg,
		.iov_len = sizeof(reply_msg),
	};
	dserver_rpc_hooks_msghdr_t replymsg = {
		.msg_name = NULL,
		.msg_namelen = 0,
		.msg_iov = &reply_data,
		.msg_iovlen = 1,
		.msg_control = controlbuf,
		.msg_controllen = sizeof(controlbuf),
	};

	dserver_rpc_hooks_atomic_save_t atomic_save;
	dserver_rpc_hooks_atomic_begin(&atomic_save);

	long int long_status;

retry_send:
	long_status = dserver_rpc_hooks_send_message(server_socket, &callmsg);

	if (long_status == dserver_rpc_hooks_get_interrupt_status()) {
		goto retry_send;
	}

	if (long_status < 0) {
		dserver_rpc_hooks_atomic_end(&atomic_save);
		dserver_rpc_hooks_printf("*** %d:%d: %s: BAD SEND STATUS: %ld ***\n", dserver_rpc_hooks_get_pid(), dserver_rpc_hooks_get_tid(), __func__, long_status);
		return (int)long_status;
	}

	if (long_status != sizeof(call)) {
		dserver_rpc_hooks_atomic_end(&atomic_save);
		dserver_rpc_hooks_printf("*** %d:%d: %s: BAD SEND LENGTH: %ld (expected %zu) ***\n", dserver_rpc_hooks_get_pid(), dserver_rpc_hooks_get_tid(), __func__, long_status, sizeof(call));
		return dserver_rpc_hooks_get_communication_error_status();
	}

retry_receive:
	long_status = dserver_rpc_hooks_receive_message(server_socket, &replymsg);

	if (long_status == dserver_rpc_hooks_get_interrupt_status()) {
		goto retry_receive;
	}

	if (long_status < 0) {
		dserver_rpc_hooks_atomic_end(&atomic_save);
		dserver_rpc_hooks_printf("*** %d:%d: %s: BAD RECEIVE STATUS: %ld ***\n", dserver_rpc_hooks_get_pid(), dserver_rpc_hooks_get_tid(), __func__, long_status);
		return (int)long_status;
	}

	if (long_status < sizeof(dserver_rpc_replyhdr_t)) {
		dserver_rpc_hooks_atomic_end(&atomic_save);
		dserver_rpc_hooks_printf("*** %d:%d: %s: BAD RECEIVE MESSAGE: length=%ld (expected %zu) ***\n", dserver_rpc_hooks_get_pid(), dserver_rpc_hooks_get_tid(), __func__, long_status, sizeof(reply_msg.reply));
		return dserver_rpc_hooks_get_communication_error_status();
	}

	if (reply_msg.reply.header.number != dserver_callnum_debug_list_members) {
		dserver_rpc_hooks_atomic_end(&atomic_save);
		dserver_rpc_hooks_printf("*** %d:%d: %s: BAD RECEIVE MESSAGE: number=%d (expected %d), code=%d, length=%ld (expected %zu) ***\n", dserver_rpc_hooks_get_pid(), dserver_rpc_hooks_get_tid(), __func__, reply_msg.reply.header.number, dserver_callnum_debug_list_members, reply_msg.reply.header.code, long_status, sizeof(reply_msg.reply));
		return dserver_rpc_hooks_get_communication_error_status();
	}

	if (long_status != sizeof(reply_msg.reply)) {
		dserver_rpc_hooks_atomic_end(&atomic_save);
		dserver_rpc_hooks_printf("*** %d:%d: %s: BAD RECEIVE MESSAGE: number=%d (expected %d), code=%d, length=%ld (expected %zu) ***\n", dserver_rpc_hooks_get_pid(), dserver_rpc_hooks_get_tid(), __func__, reply_msg.reply.header.number, dserver_callnum_debug_list_members, reply_msg.reply.header.code, long_status, sizeof(reply_msg.reply));
		return dserver_rpc_hooks_get_communication_error_status();
	}

	dserver_rpc_hooks_atomic_end(&atomic_save);

	valid_fd_count = 0;
	if (reply_msg.reply.body.fd >= 0) {
		++valid_fd_count;
	}
	if (valid_fd_count > 0) {
		dserver_rpc_hooks_cmsghdr_t* reply_cmsg = DSERVER_RPC_HOOKS_CMSG_FIRSTHDR(&replymsg);
		if (!reply_cmsg || reply_cmsg->cmsg_level != DSERVER_RPC_HOOKS_SOL_SOCKET || reply_cmsg->cmsg_type != DSERVER_RPC_HOOKS_SCM_RIGHTS || reply_cmsg->cmsg_len != DSERVER_RPC_HOOKS_CMSG_LEN(sizeof(int) * valid_fd_count)) {
			return dserver_rpc_hooks_get_bad_message_status();
		}
		dserver_rpc_hooks_memcpy(fds, DSERVER_RPC_HOOKS_CMSG_DATA(reply_cmsg), sizeof(int) * valid_fd_count);
	}
	if (out_port_count) {
		*out_port_count = reply_msg.reply.body.port_count;
	}
	if (out_fd) {
		*out_fd = (reply_msg.reply.body.fd >= 0) ? fds[reply_msg.reply.body.fd] : -1;
	} else if (reply_msg.reply.body.fd >= 0) {
		dserver_rpc_hooks_close_fd(fds[reply_msg.reply.body.fd]);
	}
	return reply_msg.reply.header.code;
};

